// Mock-data read tests for NetcdfSharp.Core.
// The mock files are generated by ..\generate_mock_data.py (output: ..\mock-datasets, gitignored).
// If the data is absent, tests pass with a message so the suite stays green without the (generated)
// binary test data; run `python generate_mock_data.py` (from the repo root) to produce it.


using System;
using System.IO;
using NetcdfSharp.ucar.ma2;
using NetcdfSharp.ucar.nc2;
using NetcdfSharp.ucar.nc2.constants;
using Xunit;

namespace NetcdfSharp.ucar.tests
{

	/// <summary>
	/// Reads the generated mock netCDF/HDF5/HDF4 files and verifies structure + data access.
	/// Coverage: per-format opens, the full data-type matrix, group + variable metadata,
	/// scale/offset and fill values, and section (hyperslab) reads.
	/// </summary>
	public class MockDataReadTests
	{
		// ------------------------------------------------------------------
		// netCDF-3: structure + data type matrix
		// ------------------------------------------------------------------


		[Fact]
		public void Netcdf3File_OpensAndReads()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_netcdf3.nc"))
			{
				if (nc == null)
				{
					return; // run generate_mock_data.py to create mock data

				}
				Assert.NotNull(nc);

				MockDataSupport.AssertVar(nc, "temperature", DataType.FLOAT, new int[] { 10, 5, 8 });
				MockDataSupport.AssertVar(nc, "pressure", DataType.INT, new int[] { 10, 5, 8 });
				MockDataSupport.AssertVar(nc, "humidity", DataType.SHORT, new int[] { 10, 5, 8 });
				MockDataSupport.AssertVar(nc, "quality_flags", DataType.BYTE, new int[] { 10, 5, 8 });

				Variable temp = MockDataSupport.FindVar(nc, "temperature");
				NcArray data = MockDataSupport.readAll(nc, temp);
				Assert.Equal(10L * 5 * 8, data.Size);
				Assert.False(double.IsNaN(data.getDouble(0)));
			}
		}

		[Fact]
		public void Netcdf3File_ReadsEachNumericDataType()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_netcdf3.nc"))
			{
				if (nc == null)
				{
					return;
				}

				// float
				NcArray t = MockDataSupport.readAll(nc, MockDataSupport.FindVar(nc, "temperature"));
				Assert.Equal(DataType.FLOAT, t.DataType);
				Assert.False(float.IsNaN(t.getFloat(0)));

				// int
				NcArray p = MockDataSupport.readAll(nc, MockDataSupport.FindVar(nc, "pressure"));
				int iv = p.getInt(0);
				Assert.True(iv >= -9999 && iv < 2000, "pressure value " + iv + " out of expected range");

				// short
				NcArray h = MockDataSupport.readAll(nc, MockDataSupport.FindVar(nc, "humidity"));
				short sv = h.getShort(0);
				Assert.True(sv >= -32768 && sv < 30000, "humidity value " + sv + " out of expected range");

				// byte (unsigned in this port)
				NcArray q = MockDataSupport.readAll(nc, MockDataSupport.FindVar(nc, "quality_flags"));
				byte bv = q.getByte(0);
				Assert.True(bv <= 3, "flag value " + bv + " out of expected range");
			}
		}

		[Fact]
		public void Netcdf3File_ReadsDoubleAndCharTypes()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_netcdf3.nc"))
			{
				if (nc == null)
				{
					return;
				}

				// double coordinate var: time = [0, 6, 12, ...]
				Variable time = MockDataSupport.AssertVar(nc, "time", DataType.DOUBLE, new int[] { 10 });
				NcArray ta = MockDataSupport.readAll(nc, time);
				Assert.Equal(0.0, ta.getDouble(0));
				Assert.Equal(9.0 * 6, ta.getDouble(9));

				// float coordinates
				Variable lat = MockDataSupport.AssertVar(nc, "lat", DataType.FLOAT, new int[] { 5 });
				Assert.Equal(-90.0, MockDataSupport.readAll(nc, lat).getDouble(0), 1e-5);
				Assert.Equal(90.0, MockDataSupport.readAll(nc, lat).getDouble(4), 1e-5);

				// char: fixed-length S1 strings [lat, 20]
				Variable names = MockDataSupport.AssertVar(nc, "station_names", DataType.CHAR, new int[] { 5, 20 });
				NcArray na = MockDataSupport.readAll(nc, names);
				Assert.Equal(5L * 20, na.Size);
				// first char of the first name, "STATION_00" -> 'S'
				Assert.Equal('S', na.getChar(0));
			}
		}

		[Fact]
		public void Netcdf3File_ReadsScalarConversions()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_netcdf3.nc"))
			{
				if (nc == null)
				{
					return;
				}
				// the same float value read through double/float accessors agrees
				NcArray t = MockDataSupport.readAll(nc, MockDataSupport.FindVar(nc, "temperature"));
				double d = t.getDouble(0);
				float f = t.getFloat(0);
				Assert.Equal(d, (double)f, 1e-6);
			}
		}

		[Fact]
		public void Netcdf3File_ReadsSectionHyperslab()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_netcdf3.nc"))
			{
				if (nc == null)
				{
					return;
				}
				Variable temp = MockDataSupport.FindVar(nc, "temperature");
				Section s = Section.fill(new Section(new NcRange(0, 2), new NcRange(0, 2), new NcRange(0, 3)), temp.Shape);
				NcArray h = nc.readData(temp, s);
				Assert.Equal(new int[] { 3, 3, 4 }, h.Shape);
				Assert.Equal(3L * 3 * 4, h.Size);
			}
		}

