		[Fact]
		public void Netcdf3File_ReadsVariableAttributes()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_netcdf3.nc"))
			{
				if (nc == null)
				{
					return;
				}
				Variable temp = MockDataSupport.FindVar(nc, "temperature");
				Assert.NotNull(temp);
				Assert.Equal("K", temp.findAttributeString("units", null));
				Assert.Equal("air_temperature", temp.findAttributeString("standard_name", null));
				Assert.Equal("Air Temperature", temp.findAttributeString("long_name", null));
				Assert.Equal("lat lon", temp.findAttributeString("coordinates", null));

				// scale_factor / add_offset present and numeric (python netCDF4 stores these as f8/double)
				NetcdfSharp.ucar.nc2.NcAttribute scale = temp.findAttribute("scale_factor");
				Assert.NotNull(scale);
				Assert.Equal(0.1f, Convert.ToSingle(scale.NumericValue));
				NetcdfSharp.ucar.nc2.NcAttribute offset = temp.findAttribute("add_offset");
				Assert.NotNull(offset);
				Assert.Equal(273.15f, Convert.ToSingle(offset.NumericValue));

				Variable humidity = MockDataSupport.FindVar(nc, "humidity");
				Assert.Equal("percent", humidity.findAttributeString("units", null));
				Assert.NotNull(humidity.findAttribute("scale_factor"));
				Assert.NotNull(humidity.findAttribute("add_offset"));
			}
		}

		// ------------------------------------------------------------------
		// scale_factor / add_offset: attributes are present; the raw NetcdfFile
		// read does NOT apply them (enhancement is out of scope), so values are
		// the stored packed values.
		// ------------------------------------------------------------------


		[Fact]
		public void Netcdf3File_ScaleOffsetMetadataPresent()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_netcdf3.nc"))
			{
				if (nc == null)
				{
					return;
				}
				Variable temp = MockDataSupport.FindVar(nc, "temperature");
				Assert.NotNull(temp);
				float scale = Convert.ToSingle(temp.findAttribute(CDM.SCALE_FACTOR).NumericValue);
				float offset = Convert.ToSingle(temp.findAttribute(CDM.ADD_OFFSET).NumericValue);
				Assert.Equal(0.1f, scale);
				Assert.Equal(273.15f, offset);

				// raw read returns stored (packed) values, not scaled
				NcArray t = MockDataSupport.readAll(nc, temp);
				double first = t.getDouble(0);
				Assert.True(first > -1000 && first < 1000, "raw value " + first + " unexpectedly large (scale/offset should NOT be applied on NetcdfFile.readData)");

				// manual application of scale/offset yields the physical value
				Assert.False(double.IsNaN(first * scale + offset));
			}
		}

