		[Fact]
		public void Hdf5File_ReadsDatasets()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_hdf5.h5"))
			{
				if (nc == null)
				{
					return;
				}
				Variable temp = MockDataSupport.AssertVar(nc, "sensor_data/temperature", DataType.FLOAT, new int[] { 100, 50, 30 });
				Assert.False(double.IsNaN(MockDataSupport.readAll(nc, temp).getDouble(0)));

				Variable counts = MockDataSupport.AssertVar(nc, "sensor_data/counts", DataType.INT, new int[] { 100, 50 });
				NcArray data = MockDataSupport.readAll(nc, counts);
				Assert.Equal(100L * 50, data.Size);
