		}

		[Fact]
		public void Hdf5File_ReadsDoubleAndScalar()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_hdf5.h5"))
			{
				if (nc == null)
				{
					return;
				}
				// 2-D double dataset
				Variable gz = MockDataSupport.AssertVar(nc, "compressed_data/gzip_compressed", DataType.DOUBLE, new int[] { 1000, 1000 });
				NcArray g = MockDataSupport.readAll(nc, gz);
				Assert.Equal(1000L * 1000, g.Size);
				Assert.False(double.IsNaN(g.getDouble(0)));

				// scalar (rank 0) double dataset
				Variable scalar = MockDataSupport.FindVar(nc, "metadata/scalar_value");
				Assert.NotNull(scalar);
				Assert.Equal(DataType.DOUBLE, scalar.DataType);
				Assert.Empty(scalar.Shape);
				NcArray s = MockDataSupport.readAll(nc, scalar);
				Assert.Equal(1L, s.Size);
				Assert.Equal(42.0, s.getDouble(0));
			}
		}

		[Fact]
		public void Hdf5File_ReadsEnumTypedef()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_hdf5.h5"))
			{
				if (nc == null)
				{
					return;
				}
				Variable weather = MockDataSupport.AssertVar(nc, "sensor_data/weather_type", DataType.ENUM1, new int[] { 100 });
				Assert.NotNull(weather.EnumTypedef);

				// enum map from python h5py: {0: clear, 1: cloudy, 2: rain, 3: snow}
				Assert.Equal("clear", weather.EnumTypedef.lookupEnumString(0));
				Assert.Equal("cloudy", weather.EnumTypedef.lookupEnumString(1));
				Assert.Equal("rain", weather.EnumTypedef.lookupEnumString(2));
				Assert.Equal("snow", weather.EnumTypedef.lookupEnumString(3));

				// data reads back as the underlying byte value in range
				NcArray a = MockDataSupport.readAll(nc, weather);
				int[] cnt = new int[4];
				for (int i = 0; i < a.Size; i++)
				{
					cnt[a.getByte(i)]++;
				}
				Assert.Equal(100L, a.Size);
				Assert.Equal(100, cnt[0] + cnt[1] + cnt[2] + cnt[3]);
			}
		}

		[Fact]
		public void Hdf5File_ReadsSectionHyperslab()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_hdf5.h5"))
			{
				if (nc == null)
				{
					return;
				}
				// chunked + gzip-compressed dataset, small hyperslab
				Variable gz = MockDataSupport.FindVar(nc, "compressed_data/gzip_compressed");
				Section s = Section.fill(new Section(new NcRange(0, 4), new NcRange(0, 4)), gz.Shape);
				NcArray h = nc.readData(gz, s);
				Assert.Equal(new int[] { 5, 5 }, h.Shape);
				Assert.False(double.IsNaN(h.getDouble(0)));
			}
		}

		// ------------------------------------------------------------------
		// HDF4: data types including unsigned byte
		// ------------------------------------------------------------------


		[Fact]
		public void Hdf4File_ReadsDatasets()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_hdf4.hdf"))
			{
				if (nc == null)
				{
					return;
				}
				Variable temp = MockDataSupport.AssertVar(nc, "temperature", DataType.FLOAT, new int[] { 10, 20, 30 });
				NcArray t = MockDataSupport.readAll(nc, temp);
				Assert.Equal(10L * 20 * 30, t.Size);
				Assert.False(float.IsNaN(t.getFloat(0)));

				Variable counts = MockDataSupport.AssertVar(nc, "counts", DataType.INT, new int[] { 15, 25 });
				NcArray c = MockDataSupport.readAll(nc, counts);
				Assert.Equal(15L * 25, c.Size);

				// pyhdf writes UINT8 -> should surface as UBYTE, values 0..255
				Variable image = MockDataSupport.AssertVar(nc, "image_data", DataType.UBYTE, new int[] { 20, 30 });
				NcArray img = MockDataSupport.readAll(nc, image);
				Assert.Equal(20L * 30, img.Size);
				byte b0 = img.getByte(0);
				Assert.True(b0 >= 0 && b0 <= 255);
			}
		}

		[Fact]
		public void Hdf4File_ReadsFillValue()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_hdf4.hdf"))
			{
				if (nc == null)
				{
					return;
				}
				// ~10% of pressure values were set to the _FillValue
				Variable pressure = MockDataSupport.AssertVar(nc, "pressure", DataType.FLOAT, new int[] { 8, 12 });
				NcArray p = MockDataSupport.readAll(nc, pressure);
				Assert.Equal(8L * 12, p.Size);
				int fills = 0;
				for (int i = 0; i < p.Size; i++)
				{
					if (p.getFloat(i) == -999.0f)
					{
						fills++;
					}
				}
				Assert.True(fills > 0, "expected some _FillValue cells in pressure");
			}
		}

