		[Fact]
		public void XarrayNetcdf4File_Reads()
		{
			using (NetcdfFile nc = MockDataSupport.TryOpen("test_xarray_netcdf4.nc"))
			{
				if (nc == null)
				{
					return;
				}
				// xarray writes doubles by default; the time coord became int64 (LONG)
				MockDataSupport.AssertVar(nc, "temperature", DataType.DOUBLE, new int[] { 30, 10, 20 });
				MockDataSupport.AssertVar(nc, "time", DataType.LONG, new int[] { 30 });

				NcArray data = MockDataSupport.readAll(nc, MockDataSupport.FindVar(nc, "temperature"));
				Assert.Equal(30L * 10 * 20, data.Size);
			}
		}

